package com.backendSupermercado.supermercasdo.modules.lotes.controller;
import java.time.LocalDate; import org.springframework.data.domain.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import lombok.RequiredArgsConstructor; import com.backendSupermercado.supermercasdo.modules.lotes.dto.LoteResponseDto; import com.backendSupermercado.supermercasdo.modules.lotes.service.LoteService;
@RestController @RequestMapping("/api/inventario/lotes") @RequiredArgsConstructor public class LoteController { private final LoteService service; @GetMapping public ResponseEntity<Page<LoteResponseDto>> listar(@RequestParam(required=false)String buscar,@RequestParam(required=false)Long idProducto,@RequestParam(required=false)String estado,@RequestParam(required=false)LocalDate fechaDesde,@RequestParam(required=false)LocalDate fechaHasta,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="8")int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Paginación inválida");return ResponseEntity.ok(service.listar(buscar,idProducto,estado,fechaDesde,fechaHasta,PageRequest.of(page,size,Sort.by("fechaVencimiento").ascending())));}}
